<?php
declare(strict_types=1);
$root=dirname(__DIR__); $new=file_get_contents($root.'/public/plataforma/empresa-nova.php'); $detail=file_get_contents($root.'/public/plataforma/empresa.php'); $fiscal=file_get_contents($root.'/public/includes/establishment_form.php'); $erp=file_get_contents($root.'/public/index.php'); $data=file_get_contents($root.'/src/Services/EstablishmentData.php'); $migration=file_get_contents($root.'/migrations/20260821_create_tenant_establishments.sql'); $contract=file_get_contents($root.'/docs/fiscal/contracts/establishment.md');
function onboardingAssert(bool $ok,string $message):void{if(!$ok){fwrite(STDERR,"ASSERTION FAILED: {$message}\n");exit(1);}}
foreach(['razao_social','nome_fantasia','cnpj','slug'] as $field) onboardingAssert(str_contains($new,'name="'.$field.'"'),"general field {$field}"); foreach(['Identificação','Provisionamento','Fiscal','Confirmação'] as $step) onboardingAssert(str_contains($new,$step),"onboarding step {$step}"); onboardingAssert(str_contains($new,"created['tenant_id']"),'new company continues to detail');
$persistent=['tax_id','legal_name','trade_name','state_registration','st_registration','municipal_registration','cnae','tax_regime_code','street','number','complement','district','city_ibge_code','city_name','state','postal_code','country_code','country_name','phone','email','status']; foreach($persistent as $field){onboardingAssert(str_contains($fiscal,'name="'.$field.'"'),"visual field {$field}");onboardingAssert(str_contains($data,"'{$field}'"),"backend field {$field}");onboardingAssert(str_contains($migration,$field),"schema field {$field}");onboardingAssert(str_contains($contract,"`{$field}`"),"contract field {$field}");}
onboardingAssert(str_contains($detail,'EstablishmentFiscalCompleteness'),'detail calculates fiscal completeness'); onboardingAssert(str_contains($detail,'empresa-fiscal-config.php')&&str_contains($detail,'Produção fiscal'),'operational fiscal configuration and blocked production visible'); onboardingAssert(str_contains($detail,'resolveAdministrative($context)'),'panel uses administrative context'); onboardingAssert(!str_contains($detail,'$_SESSION' . "['tenant_id']"),'panel does not mutate tenant session'); onboardingAssert(str_contains($erp,'TenantEstablishmentRepository'),'ERP uses same canonical repository'); onboardingAssert(!str_contains($new,'state_registration'),'new MAIN form does not receive fiscal fields'); onboardingAssert(!str_contains($fiscal,'name="certificate')&&!str_contains($fiscal,'name="csc'),'certificate and CSC stay out of issuer form'); onboardingAssert(!str_contains($detail,'SEFAZ')&&!str_contains($detail,'generateXml'),'no emission implementation'); echo "PlatformFiscalOnboarding OK\n";
